<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Services\OrganizationService;use InaudisVote\Services\UserService;$user=Authorization::requireRoles(['admin']);$error=null;$message=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::validate($_POST['_csrf']??null)){$error='Solicitud inválida.';}else{try{$action=(string)($_POST['action']??'create');if($action==='toggle'){UserService::toggleStatus((int)($_POST['user_id']??0));$message='Estado actualizado.';}else{UserService::create($_POST);$message='Usuario creado.';}}catch(Throwable $e){$error=$e->getMessage();}}}$users=UserService::all();$organizations=OrganizationService::all();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios | QUORUM</title><link rel="stylesheet" href="/assets/quorum.css"></head><body class="vota-ui"><div class="v-shell"><aside class="v-sidebar"><div class="v-brand"><img class="v-brandmark" src="/assets/quorum-mark.svg" alt=""><span><span class="v-brand-name">QUORUM<small>by INAUDIS</small></span></span></div><nav class="v-nav"><a href="/dashboard.php">⌂ &nbsp; Inicio</a><a href="/elections.php">✓ &nbsp; Votaciones</a><a href="/organizations.php">▦ &nbsp; Organizaciones</a><a class="active" href="/users.php">♙ &nbsp; Usuarios</a><a href="/audit.php">◷ &nbsp; Auditoría</a></nav><div class="v-sidebar-foot"><?=htmlspecialchars($user['name'])?></div></aside><div class="v-main"><header class="v-topbar"><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content"><div class="v-headrow"><div><div class="v-kicker">Accesos y roles</div><h1 class="v-title">Usuarios administrativos</h1><div class="v-accent-line"></div><p class="v-subtitle">Controla quién administra QUORUM y cada organización.</p></div></div><?php if($message):?><div class="v-alert v-alert-ok"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="v-grid-2"><section class="v-card v-pad"><h2 style="margin-top:0">Nuevo usuario</h2><form method="post" class="v-stack"><?=Csrf::input()?><input type="hidden" name="action" value="create"><input class="v-field" name="name" required placeholder="Nombre"><input class="v-field" name="email" type="email" required placeholder="Email"><input class="v-field" name="password" type="password" minlength="8" required placeholder="Contraseña inicial"><select class="v-field" name="role"><option value="organizer">Organizador</option><option value="witness">Ministro de Fe</option><option value="admin">Administrador INAUDIS</option></select><select class="v-field" name="organization_id"><option value="">Sin organización / Admin</option><?php foreach($organizations as $o):?><option value="<?=$o['id']?>"><?=htmlspecialchars($o['name'])?></option><?php endforeach;?></select><button class="v-btn v-btn-orange">Crear usuario</button></form></section><section class="v-card v-pad v-table-wrap"><div class="v-section-head"><h2 style="margin:0">Accesos</h2><span class="v-muted"><?=count($users)?> usuarios</span></div><table class="v-table"><thead><tr><th>Nombre</th><th>Email</th><th>Rol</th><th>Organización</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=htmlspecialchars($u['name'])?></strong></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['role'])?></td><td><?=htmlspecialchars((string)$u['organization_name'])?></td><td><span class="v-status <?=$u['status']==='active'?'v-status-open':'v-status-draft'?>"><?=htmlspecialchars($u['status'])?></span></td><td><?php if((int)$u['id']!==(int)$user['id']):?><form method="post"><?=Csrf::input()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="v-btn v-btn-outline" style="padding:7px 9px">Cambiar estado</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section></div></main></div></div></body></html>